package com.google.javascript.jscomp;

import com.google.common.base.Function;
import com.google.common.collect.ImmutableMap;
import com.google.javascript.jscomp.AbstractIterator.CheckedIterator;
import com.google.javascript.jscomp.phases.AbstractPass;
import com.google.javascript.jscomp.types.JSType;
import com.google.javascript.jscomp.types.TypeError;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.jstype.FunctionType;
import com.google.javascript.rhino.jstype.JSType;
import com.google.javascript.rhino.jstype.JSTypeRegistry;
import com.google.javascript.rhino.jstype.ObjectType;
import com.google.javascript.rhino.jstype.Visitor;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;
import static com.google.javascript.jscomp.Assertions.assertNotNull;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class ClosureReverseAbstractInterpreter_getPreciserScopeKnowingConditionOutcome_TriageGen0Test {

  private ClosureReverseAbstractInterpreter interpreter;
  private FlowScope blindScope;
  private Map<String, Function<TypeRestriction, JSType>> restricters;

  // Mocking internal components required for the method
  @Mock
  private Node condition;

  @Before
  public void setUp() {
    // Since we cannot easily instantiate the full ClosureReverseAbstractInterpreter 
    // without a complex compiler setup, we use a spy on a mock or a subclass.
    interpreter = spy(new ClosureReverseAbstractInterpreter());
    blindScope = mock(FlowScope.class);
    restricters = new HashMap<>();

    // Injecting the restricters map via reflection if it's private, 
    // but assuming for this test context we can manipulate the state.
    // In a real scenario, one would use a test subclass or reflection.
    setRestricters(interpreter, restricters);
  }

  @Test
  public void testDefaultPath_CallsNextPreciser() {
    when(condition.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.OTHER);
    FlowScope expectedScope = mock(FlowScope.class);
    when(interpreter.nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true))
        .thenReturn(expectedScope);

    FlowScope actualScope = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

    assertEquals(expectedScope, actualScope);
    verify(interpreter, never()).restrictParameter(any(), any(), any(), any(), anyBoolean());
  }

  @Test
  public void testConditionNotCall() {
    when(condition.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.OTHER);
    interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
    verify(interpreter).nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
  }

  @Test
  public void testConditionCallButWrongChildCount() {
    when(condition.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.CALL);
    when(condition.getChildCount()).thenReturn(1);

    interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
    verify(interpreter).nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
  }

  @Test
  public void testConditionCallWithTwoChildrenButCalleeNotGetProp() {
    when(condition.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.CALL);
    when(condition.getChildCount()).thenReturn(2);

    Node callee = mock(Node.class);
    when(condition.getFirstChild()).thenReturn(callee);
    when(callee.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.NAME);

    interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
    verify(interpreter).nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
  }

  @Test
  public void testConditionCallButParamIsNotQualifiedName() {
    when(condition.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.CALL);
    when(condition.getChildCount()).thenReturn(2);

    Node callee = mock(Node.class);
    Node param = mock(Node.class);
    when(condition.getFirstChild()).thenReturn(callee);
    when(condition.getLastChild()).thenReturn(param);

    when(callee.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.GETPROP);
    when(param.isQualifiedName()).thenReturn(false);

    interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
    verify(interpreter).nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
  }

  @Test
  public void testConditionCallButParamTypeIsNull() {
    setupStandardCallStructure();
    Node param = condition.getLastChild();

    // Mock getTypeIfRefinable to return null
    doReturn(null).when(interpreter).getTypeIfRefinable(eq(param), eq(blindScope));

    interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
    verify(interpreter).nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
  }

  @Test
  public void testConditionCallButLeftNotGoog() {
    setupStandardCallStructure();
    Node param = condition.getLastChild();
    JSType paramType = mock(JSType.class);
    doReturn(paramType).when(interpreter).getTypeIfRefinable(eq(param), eq(blindScope));

    Node callee = condition.getFirstChild();
    Node left = callee.getFirstChild();
    when(left.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.NAME);
    when(left.getString()).thenReturn("notgoog");

    interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
    verify(interpreter).nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
  }

  @Test
  public void testConditionCallButRightNotString() {
    setupStandardCallStructure();
    Node param = condition.getLastChild();
    JSType paramType = mock(JSType.class);
    doReturn(paramType).when(interpreter).getTypeIfRefinable(eq(param), eq(blindScope));

    Node callee = condition.getFirstChild();
    Node left = callee.getFirstChild();
    Node right = callee.getLastChild();

    when(left.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.NAME);
    when(left.getString()).thenReturn("goog");
    when(right.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.NAME); // Not STRING

    interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
    verify(interpreter).nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
  }

  @Test
  public void testConditionCallButNoRestricterFound() {
    setupStandardCallStructure();
    Node param = condition.getLastChild();
    JSType paramType = mock(JSType.class);
    doReturn(paramType).when(interpreter).getTypeIfRefinable(eq(param), eq(blindScope));

    Node callee = condition.getFirstChild();
    Node left = callee.getFirstChild();
    Node right = callee.getLastChild();

    when(left.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.NAME);
    when(left.getString()).thenReturn("goog");
    when(right.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.STRING);
    when(right.getString()).thenReturn("unknown_key");

    interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
    verify(interpreter).nextPreciserScopeKnowingConditionOutcome(condition, blindScope, true);
  }

  @Test
  public void testSuccessfulRestriction() {
    setupStandardCallStructure();
    Node param = condition.getLastChild();
    JSType paramType = mock(JSType.class);
    doReturn(paramType).when(interpreter).getTypeIfRefinable(eq(param), eq(blindScope));

    Node callee = condition.getFirstChild();
    Node left = callee.getFirstChild();
    Node right = callee.getLastChild();

    when(left.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.NAME);
    when(left.getString()).thenReturn("goog");
    when(right.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.STRING);
    when(right.getString()).thenReturn("valid_key");

    @SuppressWarnings("unchecked")
    Function<TypeRestriction, JSType> mockRestricter = mock(Function.class);
    restricters.put("valid_key", mockRestricter);

    FlowScope expectedScope = mock(FlowScope.class);
    when(interpreter.restrictParameter(eq(param), eq(paramType), eq(blindScope), eq(mockRestricter), eq(true)))
        .thenReturn(expectedScope);

    FlowScope actualScope = interpreter.getPreciserScopeKnowingConditionOutcome(condition, blindScope, true);

    assertEquals(expectedScope, actualScope);
    verify(interpreter, never()).nextPreciserScopeKnowingConditionOutcome(any(), any(), anyBoolean());
  }

  private void setupStandardCallStructure() {
    when(condition.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.CALL);
    when(condition.getChildCount()).thenReturn(2);

    Node callee = mock(Node.class);
    Node param = mock(Node.class);
    when(condition.getFirstChild()).thenReturn(callee);
    when(condition.getLastChild()).thenReturn(param);

    when(callee.getType()).thenReturn(com.google.javascript.jscomp.ast.Assign.GETPROP);
    when(param.isQualifiedName()).thenReturn(true);

    Node left = mock(Node.class);
    Node right = mock(Node.class);
    when(callee.getFirstChild()).thenReturn(left);
    when(callee.getLastChild()).thenReturn(right);
  }

  private void setRestricters(ClosureReverseAbstractInterpreter interpreter, Map<String, Function<TypeRestriction, JSType>> map) {
    try {
      java.lang.reflect.Field field = ClosureReverseAbstractInterpreter.class.getDeclaredField("restricters");
      field.setAccessible(true);
      field.set(interpreter, map);
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }
}
